verify:
def skill():
    d = Symbol('d', real=True)
    ds = [s for s in solve(Eq(4/(5*d**2), Rational(4, 45)), d) if 2*s >= 0]
    assert len(ds) == 1
    dd = ds[0]
    return sum(3*abs(k - 6) for k in range(1, 11)) if dd == 3 else None

def standard():
    res = set()
    for a in range(-60, 61):
        for d in range(-20, 21):
            if d == 0:
                continue
            ak = lambda n: a + (n - 1)*d
            if abs(ak(4)) != ak(8):
                continue
            try:
                s = sum(Rational(1, ak(k)*ak(k + 1)) for k in range(1, 5))
            except ZeroDivisionError:
                continue
            if s == Rational(4, 45):
                res.add(sum(abs(ak(k)) for k in range(1, 11)))
    assert len(res) == 1
    return list(res)[0]

def unique():
    return [standard()]
